add_action( 'login_enqueue_scripts', 'perfectpixel_custom_login_logo' );
add_filter( 'login_headerurl', 'perfectpixel_custom_login_logo_url' );
add_filter( 'login_headertext', 'perfectpixel_custom_login_logo_text' );

function perfectpixel_custom_login_logo() {
	$url = trim( '{{login_logo_url}}' );
	if ( '' === $url && get_theme_mod( 'custom_logo' ) ) {
		$url = wp_get_attachment_image_url( get_theme_mod( 'custom_logo' ), 'medium' );
	}
	if ( '' === (string) $url ) {
		$url = get_site_icon_url( 192 );
	}
	if ( ! $url ) {
		return;
	}
	printf(
		'<style>#login h1 a, .login h1 a { background-image: url(%1$s); background-size: contain; background-position: center; width: 100%%; height: %2$dpx; }</style>',
		esc_url( $url ),
		max( 30, (int) '{{login_logo_height}}' )
	);
}

function perfectpixel_custom_login_logo_url() {
	return home_url( '/' );
}

function perfectpixel_custom_login_logo_text() {
	return get_bloginfo( 'name' );
}
